  assert.strictEqual(truncate('', 5), '');
});

test('truncate with n of 0 is just the ellipsis', () => {
  assert.strictEqual(truncate('abc', 0), '…');
});

test('truncate clamps negative n to 0', () => {
  assert.strictEqual(truncate('abc', -3), '…');
});

